css:
/* From Uiverse.io by aadium - Tags: card */
.__UIV_SCOPE__ .post-card {
  width: 260px;
  height: 340px;
  background: #1f1f1f;
  box-shadow: 10px 10px 20px #0c0c0c, 
              -10px -10px 20px #333333;
  padding: 10px;
  border-radius: 15px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
}

.__UIV_SCOPE__ .post-card textarea {
  resize: none;
  width: 100%;
  height: 40%;
  padding: 5px;
  font-family: Sans-serif;
  font-size: 16px;
  background-color: transparent;
  border: none;
  color: #fff;
}

.__UIV_SCOPE__ hr {
  border: 1px solid #464646;
  width: 100%;
  border-radius: 10em;
}

.__UIV_SCOPE__ .button-row {
  margin-top: 7px;
  margin-bottom: 3px;
}

.__UIV_SCOPE__ .button-row button {
  border-radius: 10px;
  border: none;
  width: 77px;
  height: 58px;
  font-family: Sans-serif;
  color: #fff;
  box-shadow: 0px 4px 4px rgba(0, 0, 0, 0.25);
  transition: all 0.3s ease-in-out;
}

.__UIV_SCOPE__ .button-row button:hover {
  transform: translateY(-5px);
  box-shadow: 0px 8px 8px rgba(0, 0, 0, 0.25);
}

.__UIV_SCOPE__ .upload {
  font-size: 14px;
  background: linear-gradient(180deg, #cecb00 0%, #ef4949 100%);
}

.__UIV_SCOPE__ .feeling {
  font-size: 14px;
  background: linear-gradient(180deg, #31c300 0%, #ab7811 100%);
}

.__UIV_SCOPE__ .life-event {
  font-size: 13.7px;
  background: linear-gradient(180deg, #ff1024 0%, #ffb34a 100%);
}

.__UIV_SCOPE__ .people {
  font-size: 13.5px;
  background: linear-gradient(180deg, #0095b7 0%, #5012ba 100%);
}

.__UIV_SCOPE__ .location {
  font-size: 14px;
  background: linear-gradient(180deg, #c329c9 0%, #2b5dff 100%);
}

.__UIV_SCOPE__ .live-video {
  font-size: 13.8px;
  background: linear-gradient(180deg, #c800ff 0%, #ff076a 51%, #ff6c6c 100%);
}

.__UIV_SCOPE__ .post {
  width: 100%;
  padding: 10px;
  margin-top: 7px;
  border: none;
  border-radius: 11px;
  font-size: 18px;
  font-family: Sans-serif;
  color: #fff;
  background-size: 200% 100%;
  background-image: linear-gradient(145deg, #ff00e1, #0000ff, #00d9ff);
  transition: 0.3s ease-out;
}

.__UIV_SCOPE__ .post:hover {
  background-position: 99%;
}
